import math

scene_id = "probe_scene"

res = list_objects(scene_id=scene_id)
if not res.ok:
    submit("unknown", evidence=["list_objects failed: " + str(res.error.code)])
else:
    objs = res.value
    best = None
    best_d = None
    for o in objs:
        c = o.get("centroid_m")
        if c is None:
            continue
        d = math.sqrt(c[0] * c[0] + c[1] * c[1] + c[2] * c[2])
        if best_d is None or d < best_d:
            best_d = d
            best = o
    if best is None:
        submit("unknown", evidence=["no object with centroid_m returned"])
    else:
        submit(
            best["label"],
            target_ids=[best["object_id"]],
            evidence=[
                "list_objects returned centroid_m for all objects; "
                "distance to camera = euclidean norm of centroid_m",
                "nearest = %s (id=%s) at %.4f m" % (best["label"], best["object_id"], best_d),
            ],
        )

